def diamond_perimeter(n):
    # Cells (x,y) such that |x| + |y| <= n
    # Boundary edges are edges between a cell in S_n and a cell not in S_n.
    # Let's count edges.
    count = 0
    for x in range(-n-1, n+2):
        for y in range(-n-1, n+2):
            # Check if (x,y) is in S_n
            if abs(x) + abs(y) <= n:
                # Neighbors
                for dx, dy in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nx, ny = x+dx, y+dy
                    if abs(nx) + abs(ny) > n:
                        count += 1
    return count

for n in range(1, 11):
    print(f"n={n}, perimeter={diamond_perimeter(n)}")

def get_perimeter(S, n):
    S_n = set()
    for (x,y) in S:
        for dx in range(-n, n+1):
            for dy in range(-(n-abs(dx)), n-abs(dx)+1):
                S_n.add((x+dx, y+dy))
    count = 0
    for (x,y) in S_n:
        for dx, dy in [(0,1), (0,-1), (1,0), (-1,0)]:
            if (x+dx, y+dy) not in S_n:
                count += 1
    return count

def test_rectangle(D, n_max):
    S0 = [(i, 0) for i in range(D)]
    for n in range(1, n_max+1):
        print(f"n={n}, perimeter={get_perimeter(S0, n)}")

print("D=10, n_max=5:")
test_rectangle(10, 5)

